# Toy test of the "same share of related pairs at every scale" liking (R1 mechanism 1).
# Sample orders on N thoughts with weight exp(-beta*E). Compare indicators NOT used in E with a true 4D scatter.
# E_multi = (r_whole-0.1)^2 + sum over size bins of (mean interval share - 0.1)^2 ; an empty bin counts as share 0.
# E_global = (r_whole-0.1)^2 only (the null).
# Orders are generated by a DAG G on labels 0..N-1 (edges i<j); the order is its transitive closure. Move: flip one edge.
import random, math, sys
N=int(sys.argv[1]); STEPS=int(sys.argv[2]); DIM=int(sys.argv[3]); RT={2:0.5,4:0.1}[DIM]
BINS=[(5,9),(10,19),(20,39)]
def closure(par):
    anc=[0]*N
    for m in range(N):
        a=0; p=par[m]
        while p:
            low=p&-p; i=low.bit_length()-1; p^=low
            a|=anc[i]|low
        anc[m]=a
    return anc
def desc_of(anc):
    d=[0]*N
    for m in range(N):
        a=anc[m]
        while a:
            low=a&-a; i=low.bit_length()-1; a^=low
            d[i]|=1<<m
    return d
def pc(x): return bin(x).count('1')
def measures(anc):
    desc=desc_of(anc)
    R=sum(pc(a) for a in anc)
    rw=R/(N*(N-1)/2)
    sums=[0.0]*len(BINS); cnt=[0]*len(BINS)
    links=0; ab=[0,0,0,0]
    for b in range(N):
        a_=anc[b]
        while a_:
            low=a_&-a_; a=low.bit_length()-1; a_^=low
            I=desc[a]&anc[b]; s=pc(I)
            if s==0: links+=1
            if s<4: ab[s]+=1
            if s>=5:
                rel=0; x=I
                while x:
                    l2=x&-x; i=l2.bit_length()-1; x^=l2
                    rel+=pc(anc[i]&I)
                r=rel/(s*(s-1)/2)
                for k,(lo,hi) in enumerate(BINS):
                    if lo<=s<=hi: sums[k]+=r; cnt[k]+=1
    binr=[(sums[k]/cnt[k] if cnt[k] else 0.0) for k in range(len(BINS))]
    # height
    h=[1]*N
    for m in range(N):
        a=anc[m]; best=0
        while a:
            low=a&-a; i=low.bit_length()-1; a^=low
            if h[i]>best: best=h[i]
        h[m]=best+1
    mins=sum(1 for m in range(N) if anc[m]==0); maxs=sum(1 for m in range(N) if desc[m]==0)
    return dict(rw=rw,binr=binr,cnt=cnt,links=links,ab=ab,height=max(h),mins=mins,maxs=maxs)
def E_multi(ms): return (ms['rw']-RT)**2+sum((r-RT)**2 for r in ms['binr'])
def E_global(ms): return (ms['rw']-RT)**2
def sprinkle(rng):
    if DIM==2:
        pts=sorted((rng.random(),rng.random()) for _ in range(N)); pts.sort(key=lambda p:p[0]+p[1])
        par=[0]*N
        for j in range(N):
            for i in range(j):
                if pts[i][0]<pts[j][0] and pts[i][1]<pts[j][1]: par[j]|=1<<i
        return par
    pts=[]
    while len(pts)<N:
        t=rng.uniform(-1,1); x=rng.uniform(-1,1); y=rng.uniform(-1,1); z=rng.uniform(-1,1)
        if abs(t)+math.sqrt(x*x+y*y+z*z)<1: pts.append((t,x,y,z))
    pts.sort()
    par=[0]*N
    for j in range(N):
        for i in range(j):
            dt=pts[j][0]-pts[i][0]
            if dt*dt>(pts[j][1]-pts[i][1])**2+(pts[j][2]-pts[i][2])**2+(pts[j][3]-pts[i][3])**2: par[j]|=1<<i
    return par
KEYS=['rw','height','links','mins','maxs']
def summarize(name,lst):
    def av(f): 
        v=[f(m) for m in lst]; mu=sum(v)/len(v); sd=math.sqrt(sum((a-mu)**2 for a in v)/len(v)); return mu,sd
    out=[name]
    for k in KEYS: out.append("%s=%.3f(%.3f)"%((k,)+av(lambda m:m[k])))
    for i in range(3): out.append("bin%d=%.3f n=%.0f"%(i,av(lambda m:m['binr'][i])[0],av(lambda m:m['cnt'][i])[0]))
    for i in range(4): out.append("N%d=%.1f"%(i,av(lambda m:m['ab'][i])[0]))
    print("  ".join(out)); sys.stdout.flush()
def mcmc(par,Efun,beta0,beta1,rng,steps):
    par=par[:]; ms=measures(closure(par)); E=Efun(ms); samples=[]; acc=0
    for s in range(steps):
        beta=beta0*(beta1/beta0)**(min(1.0,s/(0.5*steps)))
        j=rng.randrange(1,N); i=rng.randrange(j)
        par[j]^=1<<i
        ms2=measures(closure(par)); E2=Efun(ms2)
        if E2<=E or rng.random()<math.exp(-beta*(E2-E)): ms,E=ms2,E2; acc+=1
        else: par[j]^=1<<i
        if s>=steps*0.6 and s%200==0: samples.append(ms)
    return samples,E,acc/steps
BL,BH=(30.0,3e4) if DIM==2 else (1e3,3e5)
Q0={2:0.08,4:0.02}[DIM]
rng=random.Random(11)
summarize("scatter in %dD (truth)"%DIM,[measures(closure(sprinkle(rng))) for _ in range(300)])
def randstart(q): return [sum((1<<i) for i in range(j) if rng.random()<q) for j in range(N)]
for seed in (1,2):
    rng=random.Random(seed)
    s,E,a=mcmc(randstart(Q0),E_global,BL,BH,rng,STEPS); summarize("global-only, random start %d (E=%.1e acc=%.2f)"%(seed,E,a),s)
    s,E,a=mcmc(randstart(Q0),E_multi,BL,BH,rng,STEPS); summarize("multi-scale, random start %d (E=%.1e acc=%.2f)"%(seed,E,a),s)
rng=random.Random(5)
s,E,a=mcmc(sprinkle(rng),E_multi,BH,BH,rng,STEPS); summarize("multi-scale, scatter start (E=%.1e acc=%.2f)"%(E,a),s)
